// 只读原Common接口夹具；不伪造会话或存档，不提供资源写口。
struct ReadOnly final:CommonRead {
 std::map<StableId,ActorCoreView> actors;std::map<StableId,InventoryView> inventories;std::vector<StableId> order;
 const ActorCoreView* actor(const StableId& id)const override{auto p=actors.find(id);return p==actors.end()?nullptr:&p->second;}
 const ActionCoreView* action(const StableId&)const override{return nullptr;}
 const WalletView* wallet(const StableId&)const override{return nullptr;}
 const InventoryView* inventory(const StableId& id)const override{auto p=inventories.find(id);return p==inventories.end()?nullptr:&p->second;}
 const std::vector<StableId>* members(const StableId&)const override{return nullptr;}
 const std::vector<StableId>& actor_order()const override{return order;}
 const std::vector<StableId>& action_order()const override{return order;}
 Outcome<Integer> inventory_weight(const StableId& id)const override{const auto* i=inventory(id);if(!i)return {false,{},common_failure("UnknownInventory",id).error};Integer total=0;for(const auto& lot:i->lots)total+=lot.quantity;return {true,total,{}};}
 ReadVersion read_version(const ResourceKey& r)const override{return {r,0};}
 Outcome<Integer> spendable(const StableId&)const override{return {true,0,{}};}
 Integer tick()const override{return 1;}Integer revision()const override{return 1;}
};
